#include <vector>
#include <string>

class Solution {
public:
    std::vector<int> executeInstructions(int n, std::vector<int>& startPos, std::string s) {
        int m = s.size();
        std::vector<int> ans(m, 0);

        for (int i = 0; i < m; ++i) {
            int r = startPos[0], c = startPos[1];
            int count = 0;
            for (int j = i; j < m; ++j) {
                if (s[j] == 'R') c++;
                else if (s[j] == 'L') c--;
                else if (s[j] == 'U') r--;
                else if (s[j] == 'D') r++;

                if (r >= 0 && r < n && c >= 0 && c < n) {
                    count++;
                } else {
                    break;
                }
            }
            ans[i] = count;
        }
        return ans;
    }
};

class Solution {
    public int[] executeInstructions(int n, int[] startPos, String s) {
        int m = s.length();
        int[] ans = new int[m];

        for (int i = 0; i < m; i++) {
            int r = startPos[0], c = startPos[1];
            int count = 0;
            for (int j = i; j < m; j++) {
                char ch = s.charAt(j);
                if (ch == 'R') c++;
                else if (ch == 'L') c--;
                else if (ch == 'U') r--;
                else if (ch == 'D') r++;

                if (r >= 0 && r < n && c >= 0 && c < n) {
                    count++;
                } else {
                    break;
                }
            }
            ans[i] = count;
        }
        return ans;
    }
}

