var executeInstructions = function(n, startPos, s) {
    const m = s.length;
    const ans = new Array(m).fill(0);

    for (let i = 0; i < m; i++) {
        let r = startPos[0], c = startPos[1];
        let count = 0;
        for (let j = i; j < m; j++) {
            const ch = s[j];
            if (ch === 'R') c++;
            else if (ch === 'L') c--;
            else if (ch === 'U') r--;
            else if (ch === 'D') r++;

            if (r >= 0 && r < n && c >= 0 && c < n) {
                count++;
            } else {
                break;
            }
        }
        ans[i] = count;
    }
    return ans;
};
